Let $f : X \to Y$ be a morphism in $\mathsf{Set}^{G}$. We declare
    \begin{align*}
        T_f & = [X \xleftarrow{\operatorname{id}} X \xrightarrow{\operatorname{id}} X \xrightarrow{f} Y] \\
        N_f & = [X \xleftarrow{\operatorname{id}} X \xrightarrow{f} Y \xrightarrow{\operatorname{id}} Y] \\
        R_f & = [Y \xleftarrow{f} X \xrightarrow{\operatorname{id}} X \xrightarrow{\operatorname{id}} X]
    \end{align*}

For any diagram $X \xrightarrow{f} Y \xrightarrow{g} Z$ in $\mathsf{Set}^{G}$, we declare
    \begin{align*}
        T_g \circ T_f & = T_{g \circ f} \\
        N_g \circ N_f & = N_{g \circ f} \\
        R_f \circ R_g & = R_{g \circ f}
    \end{align*}
    in $\mathcal{P}_G$.

Let $X$ be a finite $G$-set, and let $F : \mathcal{P}_G \to \mathsf{Set}$ be a $G$-semi-Tambara functor. Let $\nabla_X : X \amalg X \to X$ denote the codiagonal. We obtain operations
    \begin{align*}
        +_{F,X}     & := F(X) \times F(X) \cong F(X \amalg X) \xrightarrow{F(T_{\nabla_X})} F(X) \\
        \cdot_{F,X} & := F(X) \times F(X) \cong F(X \amalg X) \xrightarrow{F(N_{\nabla_X})} F(X) \\
    \end{align*}
    which make $(F(X), +_{F,X}, \cdot_{F,X})$ into a commutative semiring\footnote{A semiring is just like a ring, except that it need not admit additive inverses of its elements. These are also known as \emph{rigs}.}.

\label{prop:alt-def-of-Tambara-functors}
    A $G$-Tambara functor $F$ is determined (up to isomorphism) by the commutative rings $F(G/H)$ for all subgroups $H \leq G$, together with the operations
    \begin{align*}
        \operatorname{tr}_H^K     & := F(G/H) \xrightarrow{F(T_{G/H \to G/K})} F(G/K)               &  & \text{``restriction''} \\
        \operatorname{nm}_H^K     & := F(G/H) \xrightarrow{F(N_{G/H \to G/K})} F(G/K)               &  & \text{``transfer''}    \\
        \operatorname{res}_H^K    & := F(G/K) \xrightarrow{F(R_{G/H \to G/K})} F(G/H)               &  & \text{``norm''}        \\
        \operatorname{c}_{H,g} & := F(G/H) \xrightarrow{F(T_{G/H \to G/gHg^{-1}})} F(G/gHg^{-1}) &  & \text{``conjugation''}
    \end{align*}
    for all subgroups $H \leq K \leq G$ and all elements $g \in G$.

An \emph{ideal} of a Tambara functor $k$ is a kernel of a morphism from $k$. More precisely, an ideal $I$ of $k$ is a collection of subsets $I(G/H) \subseteq k(G/H)$ (for all subgroups $H \leq G$) such that there is some morphism $\varphi : k \to k'$ such that $I(G/H) = \{x \in k(G/H) : \varphi_{G/H}(x) = 0\}$ for all $H \leq G$.

    Equivalently, a collection of subsets $I(G/H) \subseteq k(G/H)$ forms an ideal if and only if the following conditions all hold:
    \begin{enumerate}
        \item $I(G/H)$ is an ideal of the commutative ring $k(G/H)$ for all $H \leq G$;
        \item $I(G/H)$ is closed under the Weyl action on $k(G/H)$ for all $H \leq G$;
        \item $I$ is closed under transfer, norm, and restriction for all inclusions of subgroups $H' \leq H \leq G$.
    \end{enumerate}

In fact, $k[x_H]$ is given by $k \boxtimes \mathcal{A}[x_H]$. For any $k$-algebra $K$, we have
    \begin{align*}
        \mathsf{Alg}_{k}(k \boxtimes \mathcal{A}[x_H], K) & \cong \mathsf{Tamb}_{G}(\mathcal{A}[x_H], K) \\
                                       & \cong K(G/H).
    \end{align*}
    This isomorphism is natural in $K$, so this verifies the desired universal property.

\label{prop:free-at-fixed-pts-is-levelwise-fg}
  For all $H\le G$,
  $\mathcal{A}_G[x_G](G/H)$ is a finitely generated ring.

Let $\mathsf{C}$ be a category admitting a terminal object. An object $x$ of $\mathsf{C}$ is said to be \emph{Nullstellensatzian} if both:
    \begin{enumerate}
        \item $x$ is not terminal;
        \item For all compact morphisms $f : x \to y$ with $y$ nonterminal, there exists a morphism $g : y \to x$ such that $g \circ f = \operatorname{id}_x$.
    \end{enumerate}

    Note that the second condition is equivalent to $x/\mathsf{C}$ being a
    Nullstellensatzian category.

\label{lem:pres-filt-colims}
    Let $\mathsf{C}$ be a category, and let $f : x \to y$ be a morphism in $\mathsf{C}$. Then
    \begin{enumerate}
        \item $\operatorname{cod} : x / \mathsf{C} \to \mathsf{C}$ preserves filtered colimits;
        \item $f^* : y / \mathsf{C} \to x / \mathsf{C}$ preserves filtered colimits.
    \end{enumerate}

\label{cor:if-g-preserves-filt-colim-then-so-do-slices-of-g}
    If $G:\mathsf{D}\to \mathsf{C}$ preserves filtered colimits, then for any
    $y\in \mathsf{D}$, $y/G:y/\mathsf{D}\to Gy/\mathsf{C}$ preserves filtered colimits.

\label{lem:right-adjoints-transfer-AC-if-left-reflects-terminal-objects}
    Let $F : \mathsf{C} \to \mathsf{D}$ be left adjoint to $G : \mathsf{D} \to \mathsf{C}$. Suppose that:
    \begin{enumerate}
        \item $G$ preserves filtered colimits and initial objects,
        \item\label{assumption:F reflects terminal objs} $F$ reflects terminal objects (at least when restricted to compact objects),
        \item $\mathsf{D}$ is Nullstellensatzian.
    \end{enumerate}
    Then $\mathsf{C}$ is Nullstellensatzian.

\label{prop:ev-at-underlying-preserves-nullstellensatzian}
  The functor $\operatorname{ev}_{G/e}: \mathsf{Tamb}_{G}\to \mathsf{CRing}^{G}$ preserves 
  Nullstellensatzian objects.

Let $k_e = k(G/e)$. We have
    \begin{align*}
        \mathsf{Alg}_{k_e}\of*{k[x_e](G/e), S} 
            & = \mathsf{Alg}_{k_e}\of*{R_e^G k[x_e], S}         \\
            & \cong \mathsf{Alg}_{k}\of*{k[x_e], C_e^G S}             \\
            & \cong \of*{C_e^G S}(G/e)                          \\
            & = \operatorname{Fun}(G,S)                                   \\
            & \cong \mathsf{Alg}_{k_e}\of*{k_e[x_g | g \in G], S}
    \end{align*}
    natural in $k(G/e)$-algebras $S$.

\label{lem:nullstellensatzian-are-fixed-pt-tam-funcs}
    If $k$ is a Nullstellensatzian Tambara functor, then 
    the counit map $k\to \underline{k(G/e)}$ is an isomorphism.
